        self.aapl_red_streak = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if any(symbol not in data.Bars for symbol in self.symbols.values()):
            return

        spy_bar = data.Bars[self.symbols["SPY"]]
        aapl_bar = data.Bars[self.symbols["AAPL"]]

        # Market-state calculations continue whenever complete daily data is available.
        if "AAPL" in self.previous_closes:
            if aapl_bar.Close < self.previous_closes["AAPL"]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = self.spy_sma.IsReady and self.aapl_rsi.IsReady
        cross_history_ready = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        )

        # Evaluate sells before buys.
        if indicators_ready and cross_history_ready:
            spy_crosses_below = (
                self.previous_spy_close >= self.previous_spy_sma
                and spy_bar.Close < self.spy_sma.Current.Value
            )

            if self.strategy_a_lot > 0 and spy_crosses_below:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_lot)
                self.strategy_b_lot = 0

            spy_crosses_above = (
                self.previous_spy_close <= self.previous_spy_sma
                and spy_bar.Close > self.spy_sma.Current.Value
            )

            if self.strategy_a_lot == 0 and spy_crosses_above:
                quantity = int(
                    0.40 * self.Portfolio.TotalPortfolioValue / spy_bar.Close
                )
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.strategy_a_lot = quantity

            if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(20000 / aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.strategy_b_lot = quantity

        # Preserve values needed for tomorrow's cross and streak calculations.
        self.previous_spy_close = spy_bar.Close
        self.previous_spy_sma = self.spy_sma.Current.Value

        for ticker, symbol in self.symbols.items():
            self.previous_closes[ticker] = data.Bars[symbol].Close
