        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        # Continuously update market-state quantities from all bars that exist.
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            close = float(bar.Close)

            if ticker == "SPY":
                self.spy_closes.Add(close)

            if ticker == "AAPL":
                self.aapl_rsi.Update(bar.EndTime, close)

                if ticker in self.previous_closes and close < self.previous_closes[ticker]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_closes[ticker] = close

        # Skip all rule evaluation when any subscribed ticker lacks today's bar.
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if self.IsWarmingUp:
            return

        if self.spy_closes.Count < 101 or not self.aapl_rsi.IsReady:
            return

        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]
        spy_close = float(data.Bars[spy].Close)
        aapl_close = float(data.Bars[aapl].Close)

        today_spy_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        yesterday_spy_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        yesterday_spy_close = self.spy_closes[1]

        spy_crosses_above = (
            yesterday_spy_close <= yesterday_spy_sma
            and spy_close > today_spy_sma
        )
        spy_crosses_below = (
            yesterday_spy_close >= yesterday_spy_sma
            and spy_close < today_spy_sma
        )

        # Evaluate all sells before any buys.
        if self.strategy_a_shares > 0 and spy_crosses_below:
            self.MarketOrder(spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_above:
            shares = int((0.40 * self.Portfolio.TotalPortfolioValue) // spy_close)
            if shares > 0:
                self.MarketOrder(spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(aapl, shares)
                    self.strategy_b_shares = shares
